#include "SecurityEvidenceRuntime.hpp"
namespace elysium::security {static double c(double v){return std::clamp(std::isfinite(v)?v:0.0,0.0,1.0);}bool SecurityEvidenceRuntime::addWitness(WitnessStatement x,std::string&w){if(!x.id||!x.witness||!x.subject||!x.claim){w="invalid witness";return false;}x.confidence=c(x.confidence);x.perception=c(x.perception);x.memory=c(x.memory);x.bias=c(x.bias);x.loyalty=c(x.loyalty);x.relationship=c(x.relationship);return witness_.emplace(x.id,x).second;}bool SecurityEvidenceRuntime::addSensor(SensorEvidence x,bool powered,bool covered,std::string&w){if(!powered||!covered){w="sensor unavailable";return false;}if(!x.id||!x.sensor||!x.subject||!x.claim){w="invalid sensor evidence";return false;}x.confidence=c(x.confidence);return sensors_.emplace(x.id,x).second;}bool SecurityEvidenceRuntime::upsertInfiltration(InfiltrationIdentity x,std::string&w){if(!x.actor||!x.method){w="invalid infiltration";return false;}x.compromise=c(x.compromise);infiltration_[x.actor]=std::move(x);return true;}std::vector<StableId>SecurityEvidenceRuntime::evidenceFor(StableId s)const{std::vector<StableId>v;for(auto&[id,x]:witness_)if(x.subject==s)v.push_back(id);for(auto&[id,x]:sensors_)if(x.subject==s)v.push_back(id);std::sort(v.begin(),v.end());return v;}}
